/**
 * One sync pass: scan the source tree and rewrite the auto-generated section of
 * `.agents/skills/farmart-dev/SKILL.md`.
 *
 * The hand-written half of SKILL.md is never touched. Everything between the
 * BEGIN/END markers is replaced wholesale, so the script owns exactly one
 * region and cannot corrupt the prose around it.
 *
 * Idempotent: when the rendered section is unchanged the file is left alone and
 * its mtime does not move, so the one-minute loop on an idle tree writes nothing.
 *
 *   node .agents/skills/farmart-dev/scripts/sync.mjs           # one pass
 *   node .agents/skills/farmart-dev/scripts/sync.mjs --quiet   # exit code only
 *
 * Exit codes: 0 clean or updated, 1 the file was not writable, 2 the scan failed.
 */

import fs from "node:fs"
import path from "node:path"
import process from "node:process"

import { readRowCounts } from "./db-counts.mjs"
import {
  collectComponents,
  collectE2E,
  collectExports,
  collectRoutes,
  collectSize,
  collectTables,
  collectTests,
  readPackage,
  renderSection,
} from "./scan.mjs"

export const BEGIN = "<!-- farmart-dev:auto:begin -->"
export const END = "<!-- farmart-dev:auto:end -->"

/** Repo-relative path of the document this script owns. */
export const SKILL = path.join(".agents", "skills", "farmart-dev", "SKILL.md")

/** Modules whose public surface is worth listing in the skill doc. */
const EXPORTED_MODULES = [
  "src/db/queries.ts",
  "src/db/seed.ts",
  "src/lib/data.ts",
  "src/lib/api.ts",
  "src/lib/api-types.ts",
  "src/lib/format.ts",
  "src/lib/sorts.ts",
  "src/lib/mermaid.ts",
  "src/lib/coverage.ts",
]

/** Collects every fact the auto-generated section renders. */
export async function scan(root = process.cwd()) {
  const rowCounts = await readRowCounts(root)

  return {
    generatedAt: new Date().toISOString().replace("T", " ").slice(0, 16) + "Z",
    nodeVersion: process.version,
    gitHead: gitHead(root),
    package: readPackage(root),
    routes: collectRoutes(root),
    components: collectComponents(root),
    tables: collectTables(root),
    exports: collectExports(root, EXPORTED_MODULES),
    tests: collectTests(root),
    e2e: collectE2E(root),
    size: collectSize(root),
    rowCounts,
  }
}

/** Replaces the marked region, or appends it when the markers are missing. */
export function splice(current, section) {
  const body = `${BEGIN}\n\n${section}\n\n${END}`

  const begin = current.indexOf(BEGIN)
  const end = current.indexOf(END)

  if (begin !== -1 && end !== -1 && end > begin) {
    return current.slice(0, begin) + body + current.slice(end + END.length)
  }

  return `${current.replace(/\s*$/, "")}\n\n${body}\n`
}

/**
 * The section with the "last run" line removed.
 *
 * The stamp is the one part of the output that changes on every run regardless of
 * the source, so comparing raw text would report a diff on every single pass and
 * make the whole file churn in git. Everything else is a pure function of the
 * tree, which is what "has this changed?" actually means here.
 */
// The stamp line ends in "._" — note the order: `\._$`, not `_\.$`. With the
// latter, the greedy `*_` eats the underscore and `\.$` has nothing left to
// match, so the line is never recognised and every run looks like a change.
const STAMP = /^_Generated by .*Last run .*\._$/m

export function contentOf(section) {
  return section.replace(STAMP, "").trim()
}

/** The stamped section to write, given the previous one to carry a stamp from. */
export function stamp(section, previous, generatedAt) {
  if (previous && contentOf(previous) === contentOf(section)) {
    // Nothing substantive moved — keep the old timestamp so the file stays byte
    // identical and the one-minute loop writes nothing on an idle repo.
    return previous
  }
  return section.replace(
    STAMP,
    `_Generated by \`farmart-dev/scripts/sync.mjs\`. ` +
      `Do not hand-edit below this line; edit the script instead. Last run ${generatedAt}._`,
  )
}

/** The region currently in the document, or "" when the markers are absent. */
export function currentSection(text) {
  const begin = text.indexOf(BEGIN)
  const end = text.indexOf(END)
  if (begin === -1 || end === -1 || end < begin) return ""
  return text.slice(begin + BEGIN.length, end).trim()
}

/**
 * Runs one pass. Resolves to `{ changed, section }` rather than throwing on a
 * non-fatal problem — the loop needs to keep going, not crash on a typo.
 */
export async function sync({ root = process.cwd(), quiet = false } = {}) {
  const target = path.join(root, SKILL)
  const current = fs.readFileSync(target, "utf8")
  const facts = await scan(root)

  const section = stamp(renderSection(facts), currentSection(current), facts.generatedAt)
  const next = splice(current, section)

  if (next === current) {
    if (!quiet) console.log("[farmart-dev] up to date")
    return { changed: false, section }
  }

  fs.writeFileSync(target, next)
  if (!quiet) {
    const delta = countChangedLines(current, next)
    console.log(`[farmart-dev] updated ${SKILL} (${delta >= 0 ? "+" : ""}${delta} lines in section)`)
  }
  return { changed: true, section }
}

function countChangedLines(before, after) {
  const section = after.slice(after.indexOf(BEGIN)).split("\n").length
  const previous = before.includes(BEGIN)
    ? before.slice(before.indexOf(BEGIN)).split("\n").length
    : 0
  return section - previous
}

function gitHead(root) {
  try {
    const head = fs.readFileSync(path.join(root, ".git", "HEAD"), "utf8").trim()
    return head.replace(/^ref: refs\/heads\//, "")
  } catch {
    return "unknown"
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const quiet = process.argv.includes("--quiet")
  sync({ quiet }).catch((error) => {
    console.error("[farmart-dev] scan failed:", error)
    process.exit(2)
  })
}